    READ_IN_MUTABLE_PARAMS;
    [[maybe_unused]] const std::uint64_t aNonceWordA = TwistMix64::DiffuseA(pNonce * 0xD5D6402DB27EBA3DULL + 0xB0E6348430B5794FULL);
