            aOrbiterH = (aWandererB + RotL64(aPrevious, 21U)) + 0x9BC875139BB1B5B7ULL;
            aOrbiterK = ((aWandererA + RotL64(aScatter, 11U)) + RotL64(aCarry, 29U)) + 0x99EE0CC527B231E8ULL;
            aOrbiterB = ((aWandererF + RotL64(aCross, 36U)) + 0x9E882441475D12D4ULL) + aTwistOrbiterAssignSaltB[(((31U - aIndex) + 5U)) & S_SALT1];
