            aOrbiterA = RotL64((aOrbiterA * 0xB2E8A43F7F09E151ULL), 51U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterK) + 0x258385E15E1A068BULL;
            aOrbiterI = (aOrbiterI ^ aOrbiterH) ^ 0x23249FBB11260D3DULL;
            aOrbiterI = RotL64((aOrbiterI * 0xB676CEE2C98DDE45ULL), 19U);
            //
            aOrbiterD = ((aOrbiterD + aOrbiterB) + 0x17EB468088BC61CDULL) + aTwistOrbiterUpdateSaltE[(((31U - aIndex) + 28U)) & S_SALT1];
            aOrbiterH = (aOrbiterH ^ aOrbiterD) ^ 0x8ADEDAD567F540E2ULL;
            aOrbiterH = RotL64((aOrbiterH * 0x5B4A834F2F93E8B3ULL), 57U);
