            //
            aScatter = (RotL64(aCross, 53U) ^ RotL64(aPrevious, 19U)) ^ (RotL64(aCarry, 3U) + RotL64(aIngress, 38U));
            aScatter = TwistMix64::DiffuseB((aScatter ^ aTwistDomainWordScatter));
            //
            aOrbiterB = (aWandererC + RotL64(aPrevious, 39U)) + 0x90EA831932A2CE99ULL;
            aOrbiterG = (aWandererA + RotL64(aCross, 23U)) + 0xAE8545F06F7E6BD2ULL;
            aOrbiterA = ((aWandererI + RotL64(aIngress, 54U)) + 0xCDB291C75A204E8BULL) + aTwistOrbiterAssignSaltC[((aIndex + 8U)) & S_SALT1];
            aOrbiterK = ((aWandererH + RotL64(aScatter, 43U)) + 0x06BF9CE13D23CCA6ULL) + aTwistOrbiterAssignSaltB[((aIndex + 18U)) & S_SALT1];
            aOrbiterC = ((aWandererE + RotL64(aPrevious, 19U)) + RotL64(aCarry, 3U)) + 0xE2B0688779D3E41DULL;
            aOrbiterE = ((aWandererF + RotL64(aCross, 11U)) + RotL64(aCarry, 27U)) + 0x7354C3459D301F59ULL;
            aOrbiterD = ((aWandererD + RotL64(aIngress, 5U)) + RotL64(aCarry, 35U)) + 0xD147617511C6777DULL;
            aOrbiterJ = (aWandererG + RotL64(aScatter, 29U)) + 0x084BC43A3FA4EB6DULL;
            aOrbiterF = (aWandererK + RotL64(aPrevious, 48U)) + 0x9599F2252E582DF3ULL;
            //
            aOrbiterB = (aOrbiterB + aOrbiterG) + 0x710CAB08527EDEDCULL;
            aOrbiterA = (aOrbiterA ^ aOrbiterB) ^ 0x81506AAF20F81722ULL;
            aOrbiterA = RotL64((aOrbiterA * 0xA7A4068C50CDE8B9ULL), 27U);
            //
            aOrbiterK = ((aOrbiterK + aOrbiterC) + 0x033F9F17CAD1B8FBULL) + aTwistOrbiterUpdateSaltB[(((31U - aIndex) + 10U)) & S_SALT1];
            aOrbiterB = (aOrbiterB ^ aOrbiterK) ^ 0x88CD147DD752AC05ULL;
            aOrbiterB = RotL64((aOrbiterB * 0x066887836270FCB1ULL), 37U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterD) + 0xA26741DE2182455CULL;
            aOrbiterK = (aOrbiterK ^ aOrbiterE) ^ 0xEB7C3A16CDA86833ULL;
            aOrbiterK = RotL64((aOrbiterK * 0x15B5E5C4C279F305ULL), 51U);
            //
            aOrbiterA = (aOrbiterA + aOrbiterE) + 0x6EC494BB9CBCBA24ULL;
            aOrbiterJ = (aOrbiterJ ^ aOrbiterA) ^ 0x71B61746B6AD6B57ULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0x193411EB26C9F415ULL), 43U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterA) + 0x171543164671AA06ULL;
            aOrbiterC = ((aOrbiterC ^ aOrbiterD) ^ 0x09CCACBAEBC5850EULL) ^ aTwistOrbiterUpdateSaltF[(((31U - aIndex) + 6U)) & S_SALT1];
            aOrbiterC = RotL64((aOrbiterC * 0x75B772EF59A09F3BULL), 21U);
