            aCross = (RotL64(aWaterLaneC[((S_BLOCK1 - aIndex + 7306U)) & S_BLOCK1], 41U) ^ RotL64(aWaterLaneD[((S_BLOCK1 - aIndex + 4152U)) & S_BLOCK1], 29U));
