            aCross = TwistMix64::DiffuseC((aCross ^ aTwistDomainWordCross));
            //
            aScatter = (RotL64(aPrevious, 19U) ^ RotL64(aCross, 34U)) + (RotL64(aCarry, 51U) + RotL64(aIngress, 5U));
            aScatter = TwistMix64::DiffuseA((aScatter ^ aTwistDomainWordScatter));
            //
            aOrbiterD = (aWandererF + RotL64(aIngress, 35U)) + 0x77B636B6504F58E2ULL;
            aOrbiterH = (aWandererB + RotL64(aScatter, 41U)) + 0x27AAC3CD34517EC4ULL;
            aOrbiterB = ((aWandererA + RotL64(aCross, 12U)) + 0x4066645AA51F4E8BULL) + aTwistOrbiterAssignSaltB[(((31U - aIndex) + 5U)) & S_SALT1];
            aOrbiterA = (((aWandererJ + RotL64(aPrevious, 27U)) + RotL64(aCarry, 41U)) + 0xEF7F4E69FD58A787ULL) + aTwistOrbiterAssignSaltF[((aIndex + 10U)) & S_SALT1];
            aOrbiterE = ((aWandererD + RotL64(aCross, 19U)) + RotL64(aCarry, 53U)) + 0x312E525D0A22DE9BULL;
            aOrbiterG = ((aWandererC + RotL64(aScatter, 5U)) + RotL64(aCarry, 29U)) + 0xF594587F6B4DC9C0ULL;
            aOrbiterC = (aWandererH + RotL64(aIngress, 57U)) + 0x685C33E031F81A7EULL;
            //
            aOrbiterD = ((aOrbiterD + aOrbiterH) + 0xBE2643E2990B995BULL) + aTwistOrbiterUpdateSaltC[(((31U - aIndex) + 21U)) & S_SALT1];
