            //
            aOrbiterG = (aOrbiterG + aOrbiterE) + 0x2D09F48CB70F4141ULL;
            aOrbiterH = (aOrbiterH ^ aOrbiterG) ^ 0x3BDF72D704E85478ULL;
            aOrbiterH = RotL64((aOrbiterH * 0x1AFD5660AA674A9BULL), 3U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterG) + 0x64C6E30B8B58DBF4ULL;
            aOrbiterD = ((aOrbiterD ^ aOrbiterC) ^ 0x5495D9DEE6B57129ULL) ^ aTwistOrbiterUpdateSaltD[((aIndex + 27U)) & S_SALT1];
            aOrbiterD = RotL64((aOrbiterD * 0x46E5E84BC8B11AEDULL), 41U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterC) + 0x98AB67A078C4E632ULL;
            aOrbiterA = (aOrbiterA ^ aOrbiterH) ^ 0xFB9EB9BEA2D59BDDULL;
            aOrbiterA = RotL64((aOrbiterA * 0x97D048CB08FE1225ULL), 11U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterA) + 0x43BD0AA435C757BEULL;
            aOrbiterG = (aOrbiterG ^ aOrbiterB) ^ 0x68F9946888DEB38DULL;
            aOrbiterG = RotL64((aOrbiterG * 0x3D5C2FAA91103723ULL), 51U);
            //
            aOrbiterE = ((aOrbiterE + aOrbiterB) + 0x5450A15B214339BCULL) + aTwistOrbiterUpdateSaltB[((aIndex + 26U)) & S_SALT1];
            aOrbiterC = (aOrbiterC ^ aOrbiterE) ^ 0x95B1AE2C6FC0C4E4ULL;
            aOrbiterC = RotL64((aOrbiterC * 0x8C174D341CB438D7ULL), 29U);
            //
            aIngress = aOrbiterC ^ RotL64(aOrbiterG, 47U);
            aIngress = aIngress + (RotL64(aOrbiterA, 39U) ^ aOrbiterH);
            aIngress = aIngress + (aOrbiterB ^ RotL64(aOrbiterE, 30U));
            aIngress = aIngress + RotL64(aOrbiterD, 23U);
            aIngress = TwistMix64::DiffuseC((aIngress + aScatter));
            //
            aWandererB = aWandererB ^ (((RotL64(aScatter, 3U) + aOrbiterA) + RotL64(aOrbiterH, 57U)) + aTwistWandererUpdateSaltC[(((31U - aIndex) + 7U)) & S_SALT1]);
            aWandererH = aWandererH + (((RotL64(aCross, 37U) + aOrbiterD) + RotL64(aOrbiterC, 19U)) + RotL64(aCarry, 43U));
