            aWandererJ = aWandererJ ^ ((RotL64(aCross, 21U) + RotL64(aOrbiterE, 29U)) + aOrbiterG);
            aWandererF = aWandererF + ((((RotL64(aIngress, 27U) + aOrbiterE) + RotL64(aOrbiterB, 41U)) + RotL64(aCarry, 5U)) + aTwistWandererUpdateSaltB[(((31U - aIndex) + 20U)) & S_SALT1]);
