            aCross ^= (RotL64(aEarthLaneC[((S_BLOCK1 - aIndex + 13184U)) & S_BLOCK1], 57U) ^ RotL64(aKeyRowReadA[((aIndex + 8800U)) & W_KEY1], 43U));
            aCross = TwistMix64::DiffuseB((aCross ^ aTwistDomainWordCross));
            //
            aScatter = (RotL64(aPrevious, 39U) ^ RotL64(aCross, 18U)) + (RotL64(aCarry, 51U) ^ RotL64(aIngress, 3U));
            aScatter = TwistMix64::DiffuseB((aScatter ^ aTwistDomainWordScatter));
            //
            aOrbiterG = (aWandererB + RotL64(aScatter, 50U)) + 0xB5E9037CE773A764ULL;
            aOrbiterB = (((aWandererI + RotL64(aPrevious, 5U)) + RotL64(aCarry, 11U)) + 0x7854C07E37EB35DCULL) + aTwistOrbiterAssignSaltD[((aIndex + 11U)) & S_SALT1];
            aOrbiterC = (((aWandererK + RotL64(aCross, 35U)) + RotL64(aCarry, 53U)) + 0xE6A0D1449520F852ULL) + aTwistOrbiterAssignSaltC[((aIndex + 25U)) & S_SALT1];
            aOrbiterE = (aWandererA + RotL64(aIngress, 27U)) + 0x18B9C7AF6EBF3863ULL;
            aOrbiterH = (aWandererC + RotL64(aCross, 11U)) + 0x7A8B2D8BBE862276ULL;
            aOrbiterD = ((aWandererH + RotL64(aIngress, 43U)) + RotL64(aCarry, 23U)) + 0x29DBEF6B284A1D49ULL;
            aOrbiterI = (aWandererG + RotL64(aScatter, 21U)) + 0x7B8213968F9D4EF8ULL;
            //
            aOrbiterG = ((aOrbiterG + aOrbiterB) + 0x5D0F648DB0D33287ULL) + aTwistOrbiterUpdateSaltC[(((31U - aIndex) + 6U)) & S_SALT1];
            aOrbiterC = (aOrbiterC ^ aOrbiterG) ^ 0x34D58F418D83DFA3ULL;
            aOrbiterC = RotL64((aOrbiterC * 0xF35E2B23C6636BD7ULL), 11U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterH) + 0x7529ED94F645F66BULL;
            aOrbiterG = (aOrbiterG ^ aOrbiterE) ^ 0x4B88E6F9EFEDC7BFULL;
            aOrbiterG = RotL64((aOrbiterG * 0x7EF63C78560A06C1ULL), 21U);
            //
            aOrbiterB = ((aOrbiterB + aOrbiterD) + 0x1081B6486D176A12ULL) + aTwistOrbiterUpdateSaltA[((aIndex + 15U)) & S_SALT1];
            aOrbiterE = ((aOrbiterE ^ aOrbiterB) ^ 0x6603F8AE845A3DECULL) ^ aTwistOrbiterUpdateSaltE[(((31U - aIndex) + 17U)) & S_SALT1];
            aOrbiterE = RotL64((aOrbiterE * 0xB424A5C86DA8FEE7ULL), 3U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterC) + 0x6196C38B7D706D19ULL;
            aOrbiterH = (aOrbiterH ^ aOrbiterD) ^ 0x8E327257B5436704ULL;
            aOrbiterH = RotL64((aOrbiterH * 0xEF409BAC565EF60FULL), 39U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterI) + 0xBC49EEC36E967F6BULL;
            aOrbiterB = ((aOrbiterB ^ aOrbiterH) ^ 0xF243F6A6B5B6BB58ULL) ^ aTwistOrbiterUpdateSaltB[((aIndex + 7U)) & S_SALT1];
            aOrbiterB = RotL64((aOrbiterB * 0x502DEF69930ED1DBULL), 51U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterG) + 0x3C9E719D9EC64234ULL;
            aOrbiterD = (aOrbiterD ^ aOrbiterI) ^ 0xABC4357F064AAE22ULL;
            aOrbiterD = RotL64((aOrbiterD * 0x3435A1794374BC21ULL), 57U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterE) + 0x26F1C86E87262B7EULL;
            aOrbiterI = (aOrbiterI ^ aOrbiterC) ^ 0x8F4662EE93EA69CBULL;
            aOrbiterI = RotL64((aOrbiterI * 0xE354DDBC104AC6EDULL), 27U);
            //
            aIngress = aOrbiterB ^ RotL64(aOrbiterC, 47U);
            aIngress = aIngress + (aOrbiterG ^ RotL64(aOrbiterE, 29U));
            aIngress = aIngress + (RotL64(aOrbiterH, 35U) ^ aOrbiterI);
            aIngress = aIngress + RotL64(aOrbiterD, 5U);
            aIngress = TwistMix64::DiffuseC((aIngress + aScatter));
            //
            aWandererH = aWandererH + ((((RotL64(aCross, 37U) + aOrbiterD) + RotL64(aOrbiterH, 43U)) + RotL64(aCarry, 57U)) + aTwistWandererUpdateSaltD[(((31U - aIndex) + 20U)) & S_SALT1]);
            aWandererK = aWandererK ^ ((RotL64(aScatter, 21U) + aOrbiterC) + RotL64(aOrbiterG, 11U));
            aWandererB = aWandererB + ((RotL64(aPrevious, 57U) + aOrbiterG) + RotL64(aOrbiterB, 36U));
            aWandererA = aWandererA ^ (((RotL64(aIngress, 13U) + aOrbiterH) + RotL64(aOrbiterE, 19U)) + aTwistWandererUpdateSaltF[(((31U - aIndex) + 18U)) & S_SALT1]);
            aWandererI = aWandererI + (((RotL64(aPrevious, 4U) + RotL64(aOrbiterB, 51U)) + aOrbiterE) + RotL64(aCarry, 23U));
            aWandererG = aWandererG ^ ((RotL64(aScatter, 47U) + aOrbiterI) + RotL64(aOrbiterG, 3U));
