            aOrbiterJ = (aOrbiterJ + aOrbiterF) + 0x4544F2CA34DD0C2DULL;
            aOrbiterI = ((aOrbiterI ^ aOrbiterJ) ^ 0xADA4F72BA252C2D9ULL) ^ aTwistOrbiterUpdateSaltC[((aIndex + 15U)) & S_SALT1];
