            aOrbiterG = (aWandererI + RotL64(aScatter, 57U)) + 0x2BB023D7B936F5E3ULL;
            aOrbiterK = (aWandererK + RotL64(aPrevious, 29U)) + 0x186710479D8F2B8BULL;
            aOrbiterD = (aWandererG + RotL64(aCross, 46U)) + 0xF41CA8E482FC3EB3ULL;
            //
            aOrbiterH = (aOrbiterH + aOrbiterA) + 0x7119D1556C9954A6ULL;
