            //
            aOrbiterA = (aOrbiterA + aOrbiterF) + 0x4D5039369761C5A7ULL;
            aOrbiterG = (aOrbiterG ^ aOrbiterA) ^ 0x148DDEE6C19F0453ULL;
            aOrbiterG = RotL64((aOrbiterG * 0x2BA9B1AC34928C13ULL), 57U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterK) + 0x1C9BF852CCBF8ADEULL;
            aOrbiterD = (aOrbiterD ^ aOrbiterG) ^ 0x6CDB324BD2512C99ULL;
