            //
            aOrbiterK = ((aOrbiterK + aOrbiterC) + 0x55F6863B85456793ULL) + aTwistOrbiterUpdateSaltD[((aIndex + 19U)) & S_SALT1];
            aOrbiterE = (aOrbiterE ^ aOrbiterK) ^ 0x2A885436D70903CEULL;
