            //
            aOrbiterF = (aOrbiterF + aOrbiterH) + 0x85662E14CBF37E87ULL;
            aOrbiterK = ((aOrbiterK ^ aOrbiterF) ^ 0x48A570DE77BC95CBULL) ^ aTwistOrbiterUpdateSaltB[((aIndex + 21U)) & S_SALT1];
            aOrbiterK = RotL64((aOrbiterK * 0xCD311562B0DC2A11ULL), 23U);
