            aWandererC = aWandererC ^ (((RotL64(aCross, 5U) + RotL64(aOrbiterH, 52U)) + aOrbiterE) + aTwistWandererUpdateSaltD[(((31U - aIndex) + 3U)) & S_SALT1]);
