            aOrbiterF = (aWandererE + RotL64(aIngress, 21U)) + 0x8890CF77A0F78A24ULL;
            aOrbiterD = (((aWandererC + RotL64(aScatter, 27U)) + RotL64(aCarry, 19U)) + 0xF2B062517B433A5CULL) + aKeyRotateAOrbiterAssignSaltC[(((31U - aIndex) + 19U)) & S_SALT1];
