            aOrbiterC = ((aOrbiterC + aOrbiterG) + 0xFB6882E2787E754BULL) + aKeyRotateAOrbiterUpdateSaltE[(((31U - aIndex) + 13U)) & S_SALT1];
            aOrbiterB = (aOrbiterB ^ aOrbiterC) ^ 0x1BCAFDFBF3ABCB73ULL;
