            aOrbiterE = RotL64((aOrbiterE * 0x239F0A8205A5B6BBULL), 11U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterH) + 0x260C3452DE326DCDULL;
            aOrbiterD = (aOrbiterD ^ aOrbiterG) ^ 0xA8779CB563DCC405ULL;
            aOrbiterD = RotL64((aOrbiterD * 0x257AAC8C4C7373E7ULL), 23U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterA) + 0x7304573263AFBABBULL;
            aOrbiterI = (aOrbiterI ^ aOrbiterB) ^ 0x19AC332C76E47DDCULL;
