            //
            aIngress = aOrbiterC ^ RotL64(aOrbiterB, 29U);
            aIngress = aIngress + (RotL64(aOrbiterJ, 23U) ^ aOrbiterF);
            aIngress = aIngress + (RotL64(aOrbiterG, 54U) ^ aOrbiterI);
            aIngress = aIngress + (RotL64(aOrbiterE, 27U) ^ aOrbiterA);
            aIngress = aIngress + (aOrbiterK ^ RotL64(aOrbiterH, 5U));
            aIngress = aIngress + RotL64(aOrbiterD, 47U);
            aIngress = TwistMix64::DiffuseA((aIngress + aScatter));
            //
            aWandererK = aWandererK ^ ((RotL64(aScatter, 51U) + RotL64(aOrbiterG, 27U)) + aOrbiterF);
            aWandererH = aWandererH + ((RotL64(aPrevious, 13U) + aOrbiterK) + RotL64(aOrbiterI, 18U));
            aWandererJ = aWandererJ ^ ((RotL64(aIngress, 18U) + RotL64(aOrbiterI, 37U)) + aOrbiterE);
