            aScatter = TwistMix64::DiffuseC((aScatter ^ aKeyRotateADomainWordScatter));
            //
            aOrbiterH = ((aWandererD + RotL64(aIngress, 51U)) + RotL64(aCarry, 23U)) + 0x6AD2CEB534D890F5ULL;
            aOrbiterK = ((aWandererC + RotL64(aPrevious, 35U)) + RotL64(aCarry, 5U)) + 0x0DC113DC9C18AC54ULL;
            aOrbiterE = (aWandererK + RotL64(aCross, 21U)) + 0x9639A51798C8513AULL;
            aOrbiterI = ((aWandererJ + RotL64(aScatter, 3U)) + RotL64(aCarry, 57U)) + 0xE667BD360F846294ULL;
            aOrbiterJ = (aWandererA + RotL64(aPrevious, 12U)) + 0xC90CCB136F32340CULL;
            aOrbiterC = ((aWandererE + RotL64(aIngress, 41U)) + 0x3E3A25238E94CED2ULL) + aKeyRotateAOrbiterAssignSaltD[((aIndex + 25U)) & S_SALT1];
            aOrbiterG = ((aWandererH + RotL64(aCross, 27U)) + 0x3699305ABBD81BD9ULL) + aKeyRotateAOrbiterAssignSaltC[(((31U - aIndex) + 17U)) & S_SALT1];
