            aOrbiterE = RotL64((aOrbiterE * 0x5ED6337DAC91F309ULL), 11U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterJ) + 0x82A56339EDF98E38ULL;
            aOrbiterK = ((aOrbiterK ^ aOrbiterI) ^ 0x03CD41630CEA23CDULL) ^ aKeyRotateAOrbiterUpdateSaltF[(((31U - aIndex) + 19U)) & S_SALT1];
