            aWandererC = aWandererC + ((((RotL64(aIngress, 39U) + aOrbiterE) + RotL64(aOrbiterH, 36U)) + RotL64(aCarry, 53U)) + aKeyRotateAWandererUpdateSaltA[((aIndex + 7U)) & S_SALT1]);
            aWandererD = aWandererD ^ (((RotL64(aScatter, 60U) + RotL64(aOrbiterJ, 27U)) + aOrbiterE) + aKeyRotateAWandererUpdateSaltB[(((31U - aIndex) + 20U)) & S_SALT1]);
