            aIngress ^= (RotL64(aPlasmaLaneB[((aIndex + 14091U)) & S_BLOCK1], 13U) ^ RotL64(aShadowLaneB[((S_BLOCK1 - aIndex + 13759U)) & S_BLOCK1], 58U));
            aIngress = TwistMix64::DiffuseC((aIngress ^ aKeyRotateADomainWordIngress));
            //
            aCross = (RotL64(aWindLaneA[((S_BLOCK1 - aIndex + 13323U)) & S_BLOCK1], 11U) ^ RotL64(aWindLaneD[((S_BLOCK1 - aIndex + 9149U)) & S_BLOCK1], 27U));
            aCross ^= (RotL64(aPoisonLaneB[((S_BLOCK1 - aIndex + 14987U)) & S_BLOCK1], 19U) ^ RotL64(aShadowLaneC[((S_BLOCK1 - aIndex + 14336U)) & S_BLOCK1], 44U));
            aCross = TwistMix64::DiffuseC((aCross ^ aKeyRotateADomainWordCross));
            //
            aScatter = (RotL64(aCarry, 41U) ^ RotL64(aPrevious, 29U)) + (RotL64(aCross, 60U) + RotL64(aIngress, 11U));
            aScatter = TwistMix64::DiffuseA((aScatter ^ aKeyRotateADomainWordScatter));
            //
            aOrbiterF = (aWandererF + RotL64(aIngress, 51U)) + 0xBF42C7B6E2B4BB34ULL;
            aOrbiterC = ((aWandererI + RotL64(aScatter, 19U)) + 0x7CE422998D23BE56ULL) + aKeyRotateAOrbiterAssignSaltE[((aIndex + 20U)) & S_SALT1];
            aOrbiterJ = (aWandererD + RotL64(aCross, 26U)) + 0x58BD196DA582499BULL;
            aOrbiterI = (((aWandererC + RotL64(aPrevious, 3U)) + RotL64(aCarry, 43U)) + 0xE545A586D17D64D5ULL) + aKeyRotateAOrbiterAssignSaltB[((aIndex + 5U)) & S_SALT1];
            aOrbiterD = ((aWandererK + RotL64(aCross, 37U)) + RotL64(aCarry, 19U)) + 0x99C340F539D170CCULL;
            aOrbiterE = (aWandererJ + RotL64(aScatter, 57U)) + 0xCEFA04A51B1E4298ULL;
            aOrbiterH = ((aWandererH + RotL64(aIngress, 11U)) + RotL64(aCarry, 57U)) + 0x09843CE65EFED121ULL;
            //
            aOrbiterF = ((aOrbiterF + aOrbiterC) + 0x9C0D72AF93043FABULL) + aKeyRotateAOrbiterUpdateSaltC[(((31U - aIndex) + 11U)) & S_SALT1];
            aOrbiterJ = ((aOrbiterJ ^ aOrbiterF) ^ 0x5DD15EB2D919D34AULL) ^ aKeyRotateAOrbiterUpdateSaltD[(((31U - aIndex) + 21U)) & S_SALT1];
            aOrbiterJ = RotL64((aOrbiterJ * 0x866994065B3C4919ULL), 13U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterJ) + 0xC3A6D672F6CE7730ULL;
            aOrbiterD = (aOrbiterD ^ aOrbiterI) ^ 0x1948CDDABEF9F453ULL;
            aOrbiterD = RotL64((aOrbiterD * 0x836A8598F14DD383ULL), 51U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterE) + 0xA48192F2E6238D94ULL;
            aOrbiterC = (aOrbiterC ^ aOrbiterD) ^ 0xE73E716204AA96F9ULL;
            aOrbiterC = RotL64((aOrbiterC * 0xEE948BD568B26EE1ULL), 3U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterF) + 0xB6F437A702BA83CDULL;
            aOrbiterI = (aOrbiterI ^ aOrbiterE) ^ 0x16D24F099F1A067DULL;
            aOrbiterI = RotL64((aOrbiterI * 0xC2474777066EA683ULL), 29U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterI) + 0x8C0ED07B57C2EE78ULL;
            aOrbiterH = (aOrbiterH ^ aOrbiterC) ^ 0x6653EF2630CA7566ULL;
            aOrbiterH = RotL64((aOrbiterH * 0x1EF248B466A22C89ULL), 57U);
            //
            aOrbiterH = ((aOrbiterH + aOrbiterD) + 0xE22C5E2D19791A5AULL) + aKeyRotateAOrbiterUpdateSaltB[(((31U - aIndex) + 3U)) & S_SALT1];
            aOrbiterF = ((aOrbiterF ^ aOrbiterH) ^ 0xAA86C31ABAA7AA18ULL) ^ aKeyRotateAOrbiterUpdateSaltF[((aIndex + 10U)) & S_SALT1];
            aOrbiterF = RotL64((aOrbiterF * 0x82273C262C371BADULL), 43U);
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterH) + 0x38BE7F24E4C66687ULL;
            aOrbiterE = (aOrbiterE ^ aOrbiterJ) ^ 0x260C250CF0198CF2ULL;
            aOrbiterE = RotL64((aOrbiterE * 0x27DD84AE854F2415ULL), 23U);
            //
            aIngress = aOrbiterI ^ RotL64(aOrbiterD, 47U);
            aIngress = aIngress + (aOrbiterC ^ RotL64(aOrbiterJ, 27U));
            aIngress = aIngress + (RotL64(aOrbiterE, 11U) ^ aOrbiterH);
            aIngress = aIngress + RotL64(aOrbiterF, 19U);
